import{_ as t,c as o,o as a,ae as s}from"./chunks/framework.CliRSA9F.js";const r="/images/command_center.webp",p=JSON.parse('{"title":"Command Center","description":"","frontmatter":{},"headers":[],"relativePath":"features/command-center.md","filePath":"features/command-center.md"}'),n={name:"features/command-center.md"};function i(h,e,l,u,c,d){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="command-center" tabindex="-1">Command Center <a class="header-anchor" href="#command-center" aria-label="Permalink to &quot;Command Center&quot;">​</a></h1><h2 id="your-podcast-s-home-base" tabindex="-1">Your Podcast&#39;s Home Base <a class="header-anchor" href="#your-podcast-s-home-base" aria-label="Permalink to &quot;Your Podcast&#39;s Home Base&quot;">​</a></h2><p>The Command Center is your starting point in PodSEO. It brings together the most important signals about your podcast&#39;s health, surfaces what needs attention, and tells you what to do next — all in one view.</p><p><img src="'+r+'" alt="Command Center Dashboard" width="600px" style="display:block;margin:0 auto;"></p><p><strong>To access</strong>: Click <strong>Command Center</strong> in the sidebar. The Command Center has four tabs across the top: <strong>Home</strong> · <strong>Planner</strong> · <strong>Positioning Strategy</strong> · <strong>Pulse</strong>. This article covers <strong>Home</strong>.</p><h2 id="what-you-ll-see" tabindex="-1"><strong>What You&#39;ll See</strong> <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;**What You&#39;ll See**&quot;">​</a></h2><h3 id="status-line" tabindex="-1"><strong>Status Line</strong> <a class="header-anchor" href="#status-line" aria-label="Permalink to &quot;**Status Line**&quot;">​</a></h3><p>At the top, a daily status message summarizes where things stand. If areas need attention, they&#39;re called out directly. This status adapts based on how recently you&#39;ve visited — if you&#39;ve been away, it highlights what changed while you were gone.</p><h3 id="optimization-score" tabindex="-1"><strong>Optimization Score</strong> <a class="header-anchor" href="#optimization-score" aria-label="Permalink to &quot;**Optimization Score**&quot;">​</a></h3><p>The main card tells you how well set up your show is: <strong>&quot;Your show is X% optimized&quot;</strong>, with an <strong>Optimization score</strong> gauge. The score reflects the inputs you control — your setup, positioning, distribution, and episode metadata. Below it, four tiles break the score down:</p><ul><li><strong>Optimization</strong> — Overall progress on setup, positioning, and distribution checks, with a link to your next recommended step</li><li><strong>Positioning</strong> — How complete your <a href="/features/positioning.html">Positioning Strategy</a> is</li><li><strong>Distribution</strong> — How many of the core listening platforms your show is available on</li><li><strong>Episode metadata</strong> — How complete your episode titles, descriptions, and other metadata are</li></ul><p>Each tile is color-coded (green, amber, or red) and links to the page where you can improve it.</p><p>Your optimization score measures what you&#39;ve put in place; it isn&#39;t the same as your visibility. Visibility is tracked separately as an outcome (see below).</p><h3 id="foundation-new-users" tabindex="-1"><strong>Foundation (New Users)</strong> <a class="header-anchor" href="#foundation-new-users" aria-label="Permalink to &quot;**Foundation (New Users)**&quot;">​</a></h3><p>When you first add a podcast, the <strong>Foundation</strong> section shows three setup steps and your progress (for example, &quot;1/3 complete&quot;):</p><ol><li><strong>Choose keywords</strong> — Set your primary keywords so you can track how your podcast ranks in search. If PodSEO picked keywords for you, the step asks you to <strong>Review keywords</strong> to confirm they match your strategy.</li><li><strong>Add competitors</strong> — Add podcasts chasing the same listeners so you can see how you compare. If PodSEO picked competitors for you, you&#39;ll be asked to <strong>Review competitors</strong>.</li><li><strong>Check platforms</strong> — Make sure your show is available across the platforms where listeners discover podcasts.</li></ol><p>Each completed step earns you <strong>10 credits</strong> you can use for <a href="/features/social-publishing.html">Social Publishing</a>. The Foundation section stays visible until you&#39;ve finished all three steps, and remains on your home page for your first couple of weeks so you can see your progress.</p><h3 id="get-your-show-seen" tabindex="-1"><strong>Get Your Show Seen</strong> <a class="header-anchor" href="#get-your-show-seen" aria-label="Permalink to &quot;**Get Your Show Seen**&quot;">​</a></h3><p>This section pairs your visibility with social promotion:</p><ul><li><strong>Visibility outcome</strong> — Shows where your podcast stands compared with other shows (for example, &quot;Top 12%&quot;) and whether it moved up or down over the last 10 days. Click <strong>Open visibility progress</strong> to see the full breakdown in <a href="/features/visibility-progress.html">Visibility Progress</a>.</li><li><strong>Social</strong> — A card that adapts to where you are with <a href="/features/social-publishing.html">Social Publishing</a>. If you haven&#39;t connected an account yet, you&#39;ll see <strong>Connect a channel</strong>. If you&#39;re connected but haven&#39;t made clips, you&#39;ll see <strong>Create clips</strong>. If clips are ready and waiting, you&#39;ll see a preview of them and a <strong>Post a clip</strong> button. Once you&#39;re posting regularly, it shows how many posts you&#39;ve published. If one of your social accounts needs to be reconnected, a warning appears above the card so you can fix it before scheduled posts are affected.</li></ul><h3 id="what-s-changing-insights" tabindex="-1"><strong>What&#39;s Changing (Insights)</strong> <a class="header-anchor" href="#what-s-changing-insights" aria-label="Permalink to &quot;**What&#39;s Changing (Insights)**&quot;">​</a></h3><p>The insights section surfaces notable movements and opportunities in your tracked market. If you&#39;ve been away for a while, this section is titled <strong>While you were away</strong> so you can catch up on what changed.</p><ul><li><strong>Competitor weakness</strong> — When a competitor loses a ranking, creating an opportunity for you to move up</li><li><strong>Rank breakthrough</strong> — When you&#39;re close to breaking into the top 10 for a keyword</li><li><strong>Falling keyword</strong> — When one of your rankings is slipping and needs attention</li><li><strong>Stale metadata</strong> — When your podcast information hasn&#39;t been updated in a while</li></ul><p>Each insight links directly to where you can take action.</p><h3 id="what-to-do-next-tasks" tabindex="-1"><strong>What to Do Next (Tasks)</strong> <a class="header-anchor" href="#what-to-do-next-tasks" aria-label="Permalink to &quot;**What to Do Next (Tasks)**&quot;">​</a></h3><p>A prioritized list of actions based on your podcast&#39;s current state and your optimization cadence. Tasks are generated from across PodSEO — keyword strategy reviews, metadata updates, competitor checks, and more. After time away, this section is titled <strong>Catch up</strong>.</p><p>If you use <a href="/features/youtube-insights.html">YouTube Insights</a>, YouTube tasks appear here too: an <strong>Activate YouTube Insights</strong> reminder when your channel is connected but Insights isn&#39;t active yet, and up to two open title suggestions (for example, adding a keyword to an episode&#39;s YouTube title). Clicking a title suggestion opens that episode directly on the YouTube page.</p><p>Priority tasks are highlighted, and overdue items show how many days have passed since they were due. Each task links to the relevant feature so you can act immediately. When nothing needs attention, you&#39;ll see <strong>You&#39;re caught up</strong> — PodSEO will surface new tasks as your data updates.</p><h2 id="other-command-center-tabs" tabindex="-1"><strong>Other Command Center Tabs</strong> <a class="header-anchor" href="#other-command-center-tabs" aria-label="Permalink to &quot;**Other Command Center Tabs**&quot;">​</a></h2><p>Alongside <strong>Home</strong>, the Command Center tabs give you access to three important features:</p><ul><li><strong><a href="/features/planner.html">Planner</a></strong> — Plan episodes, check metadata alignment, and get AI-powered content suggestions</li><li><strong><a href="/features/positioning.html">Positioning Strategy</a></strong> — Define your podcast&#39;s long-term strategic positioning</li><li><strong><a href="/features/pulse.html">Pulse</a></strong> — Discover trending topics relevant to your podcast&#39;s niche</li></ul><h2 id="strategic-use" tabindex="-1"><strong>Strategic Use</strong> <a class="header-anchor" href="#strategic-use" aria-label="Permalink to &quot;**Strategic Use**&quot;">​</a></h2><h3 id="daily-check-in" tabindex="-1"><strong>Daily Check-In</strong> <a class="header-anchor" href="#daily-check-in" aria-label="Permalink to &quot;**Daily Check-In**&quot;">​</a></h3><p>Make the Command Center your first stop when you open PodSEO. The status line and optimization score tell you immediately whether anything needs attention, saving you from checking each section individually.</p><h3 id="weekly-review" tabindex="-1"><strong>Weekly Review</strong> <a class="header-anchor" href="#weekly-review" aria-label="Permalink to &quot;**Weekly Review**&quot;">​</a></h3><p>Use the insights and tasks sections for your weekly optimization review. The Command Center aggregates signals from across PodSEO so you can prioritize your time effectively.</p><h3 id="after-changes" tabindex="-1"><strong>After Changes</strong> <a class="header-anchor" href="#after-changes" aria-label="Permalink to &quot;**After Changes**&quot;">​</a></h3><p>After updating metadata, publishing episodes, or changing your keyword strategy, check back to see how your score and insights respond. The Command Center reflects changes as PodSEO processes new data.</p><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><p>The Command Center connects to every part of PodSEO:</p><ul><li>Optimization tiles link to <strong><a href="/features/positioning.html">Positioning Strategy</a></strong>, <strong><a href="/features/distribution-health.html">Distribution Health</a></strong>, and your episode metadata; the visibility outcome links to <strong><a href="/features/visibility-progress.html">Visibility Progress</a></strong></li><li>The social card links to <strong><a href="/features/social-publishing.html">Social Publishing</a></strong></li><li>YouTube tasks link to <strong><a href="/features/youtube-insights.html">YouTube Insights</a></strong></li><li>Tasks guide you to <strong><a href="/features/planner.html">Planner</a></strong>, <strong><a href="/features/competitive-analysis.html">Competitive Analysis</a></strong>, and other features</li><li>Insights connect to <strong><a href="/features/show-rankings.html">Show Rankings</a></strong> and <strong><a href="/features/keyword-tracker.html">Keyword Tracker</a></strong> for deeper analysis</li></ul><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Start every PodSEO session at the Command Center to quickly assess what needs your attention</li><li>Don&#39;t ignore amber or red tiles — they point to inputs that are holding your podcast&#39;s discoverability back</li><li>Finish the three Foundation steps early — they give PodSEO better data to work with and earn you credits for social clips</li><li>Use the task list to stay on a regular optimization cadence rather than making changes sporadically</li><li>The insights section is especially valuable after time away — it catches you up on what changed</li></ul><p>The Command Center transforms podcast optimization from a scattered process into a focused, prioritized workflow. Let it guide your efforts toward the actions that matter most.</p><p>For a podcast that has not launched, your home is <a href="/getting-started/pre-launch-planning.html">Design and Pre-launch Planning</a> (ready soon). Agency teams can also review multiple client shows in the <a href="/features/agency-workspace.html">Agency workspace</a>.</p>',46)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
